window.deepArticles = window.deepArticles || {};

const matureEverydaySources = [
  {href:"../materialCultureReference%20-%20AltWWII.md",label:"Material Culture and Civilian Industry Reference — household systems through 1985"},
  {href:"../SoftwareDetailReference.md",label:"Software Detail Reference — mature personal computing, platforms, and networks"},
  {href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — family, political economy, social order, and mature technology"},
  {href:"../settingTimeline%20-%20AltWWII.md",label:"Setting Timeline — World Market Boom, depression, Weltnetz, and the millennium baseline"},
  {href:"../transcript.md",label:"Master Transcript, Turns 744–777 — ordinary life in 1995–2000 as an explicit development field"}
];

const matureEverydayArticle = config => ({
  category:"Social history",
  eyebrow:"Everyday life · reference year 2000",
  infoboxKicker:"Millennium household society",
  ...config,
  sources:[...matureEverydaySources,...(config.additionalSources || [])],
  categories:config.categories || ["Everyday life","Social history","Material culture","2000"]
});

Object.assign(window.deepArticles, {
  "everyday-life-in-2000": matureEverydayArticle({
    title:"Everyday life in 2000",
    infoboxKicker:"Comparative millennium social history",
    landscape:{src:"assets/diagrams/everyday-life-2000.svg",alt:"Comparison of German, Japanese, Commonwealth, American, Latin, and imperial-peripheral everyday life in 2000",caption:"A common material vocabulary—computers, electronic records, satellite links, jet travel, and automated industry—appears inside sharply different institutions"},
    lead:"Everyday life in 2000 is materially modern, widely computerized, and increasingly networked without becoming uniform or continuously connected. CRT displays, fixed telephones, paper files, cash, physical shops, repair trades, mechanical vehicles, and scheduled broadcasting coexist with personal computers, electronic records, cellular service, satellite communications, office networks, and automated production. Class, region, sex, nationality, and imperial status determine access as strongly as bloc membership.",
    canon:"Weltnetz as the common international network layer, Bridge as the principal compatibility environment, Concord as a prestigious closed ecosystem, mass household computing and games, networked offices, electronic records, home video, jet travel, nuclear grids, container ports, satellite services, distinct bloc systems, and severe metropolitan–imperial inequality are established. Household budgets, ownership rates, prices, model rosters, representative families, and exact diffusion dates remain open.",
    sections:[
      {id:"baseline",title:"Material baseline",html:"<p>A prosperous metropolitan home commonly contains mature electrical appliances, one or more CRT displays, recorded audio and video, fixed telephone service, electronic calculators, and at least one programmable device or personal computer. Film, tape, disks, printed manuals, cash, cards, and mailed documents remain in use.</p><p>Pocket cellular telephones and portable computers are familiar but not universal. Flat displays, household network appliances, digital cameras, and specialized robots remain expensive or uneven.</p>"},
      {id:"systems",title:"Five metropolitan systems",html:"<p>German households encounter certified products and Weltnetz through regulated institutions. Japanese homes combine compact electronics, console culture, company systems, and specialized domestic robotics. Commonwealth households use reliable public and commercial networks. American homes emphasize compatible platforms, modification, and corporate services. Latin households join designed professional goods to multilingual confederal institutions.</p>"},
      {id:"work",title:"Work",html:"<p>Factories, offices, hospitals, ports, shops, farms, and public agencies use computers more consistently than homes do. Automation changes scheduling, records, diagnostics, inventory, and control while preserving large technical, clerical, service, transport, construction, and care workforces.</p><p>The <a href='work-and-employment-in-2000.html'>world of work</a> is more credentialed and electronically supervised than in 1985.</p>"},
      {id:"communications",title:"Communications and media",html:"<p>Telephone, fax, broadcast, cable, satellite distribution, recorded media, electronic mail, forums, information services, and <a href='domestic-communications-in-2000.html'>Weltnetz access</a> overlap. Communication is faster without becoming one universal social feed.</p><p>National and corporate gateways preserve censorship, billing, identity, character standards, and service differences.</p>"},
      {id:"consumption",title:"Consumption and services",html:"<p>Department stores, neighborhood shops, markets, catalogs, dealerships, repair centers, banks, telephone ordering, and early network ordering coexist. Most goods still require physical inspection, delivery, installation, warranty, and service.</p><p>The American depression makes cross-bloc ownership politically suspect even where foreign consumer goods remain visible.</p>"},
      {id:"mobility",title:"Mobility",html:"<p>Private automobiles dominate American movement and remain important elsewhere, but railways, metros, buses, scooters, bicycles, ferries, and compact commercial vehicles retain larger roles in Europe and Japan. Jet travel is established; international tourism remains shaped by currency, visas, political borders, and bloc routes.</p><p>Orbital travel is prestigious professional transport, not mass tourism.</p>"},
      {id:"family",title:"Family and household",html:"<p>Marriage, kinship, churches, schools, employers, neighborhood institutions, and state or corporate benefits remain more visible than in a socially atomized consumer order. Female education and professional employment have expanded, while domestic work, childcare, elder care, and family enterprise remain major parts of household production.</p>"},
      {id:"inequality",title:"Imperial and regional inequality",html:"<p>An associated-state engineer, eastern settler, colonial subject, metropolitan technician, rural farmer, and orbital worker can all use modern systems under different rights. Infrastructure reaches farther than equal citizenship, credentials, property, or freedom of movement.</p><p><a href='everyday-life-in-imperial-peripheries-2000.html'>Imperial peripheries</a> reveal the widest separation between technical modernity and political membership.</p>"}
    ],
    related:[{href:"household-technology-in-2000.html",kicker:"Material baseline",label:"Household Technology in 2000"},{href:"work-and-employment-in-2000.html",kicker:"Occupational life",label:"Work and Employment in 2000"},{href:"domestic-communications-in-2000.html",kicker:"Media and networks",label:"Domestic Communications in 2000"},{href:"family-and-household-life-in-2000.html",kicker:"Domestic institutions",label:"Family and Household Life in 2000"},{href:"world-in-2000.html",kicker:"Political setting",label:"World in 2000"}],
    facts:[["Reference year","2000"],["Common display","Cathode-ray tube"],["Household computing","Mass but system-specific"],["International network layer","Weltnetz"],["Principal compatibility environment","Bridge"],["Ordinary mobile access","Cellular and paging, uneven"],["Ordinary purchasing","Physical retail with telephone and early network ordering"],["Largest divide","Metropolitan citizen and imperial subject"]]
  }),

  "household-technology-in-2000": matureEverydayArticle({
    title:"Household technology in 2000",
    category:"Material culture",
    infoboxKicker:"Domestic technological baseline",
    landscape:{src:"assets/diagrams/household-technology-2000.svg",alt:"Household technology layers in 2000 from utilities and appliances through media, computing, communications, and specialized automation",caption:"The millennium home is computerized and electronically serviced without being uniformly wireless, flat-screen, or continuously connected"},
    lead:"Household technology in 2000 combines mature utilities and appliances with personal computing, electronic media, telecommunications, and early domestic automation. Most homes acquire digital functions as separate products attached to older electrical and mechanical systems. The television, computer, telephone, audio system, camera, automobile, and appliance remain distinct devices rather than one universal networked platform.",
    canon:"Mass household computing and games, common Weltnetz access through several ecosystems, CRT displays, home video, electronic records, specialized Japanese household robotics, mature appliances, fixed-line continuity, uneven cellular service, and persistent physical media are established. Ownership rates, flat-panel diffusion, digital-camera shares, device prices, specific models, and national broadband schedules remain open.",
    sections:[
      {id:"utilities",title:"Utilities and appliances",html:"<p>Electricity, refrigeration, washing, cooking, heating, water, ventilation, and domestic repair remain the foundation of household technology. Electronic controls improve timers, efficiency, diagnostics, and safety without making most appliances general-purpose computers.</p>"},
      {id:"screens",title:"Screens and recorded media",html:"<p>CRT television and computer displays remain common. Video tape, optical audio, records, cassettes, disks, cartridges, and broadcast coexist with newer digital storage and distribution.</p><p>Flat panels appear in premium, portable, office, or specialist settings before becoming an ordinary large household display.</p>"},
      {id:"computers",title:"Personal computers",html:"<p>Home computers support writing, accounts, schoolwork, games, programming, design, reference, communications, and household business. Some homes possess several machines or a computer and console.</p><p>Compatibility differs by system. American machines reward expansion and modification, German machines emphasize certification, and Japanese products favor integrated ecosystems. Commonwealth computing emphasizes service and interfaces, while Latin systems combine professional design with multilingual use.</p>"},
      {id:"network",title:"Household network access",html:"<p>Modems, dedicated terminals, cable or telephone data, local service gateways, and office-linked accounts provide access to messages, information, banking, software, forums, and networked games. Weltnetz connects systems at the international layer without eliminating national services.</p><p>Always-on household access is available in leading markets but not a universal expectation.</p>"},
      {id:"personal",title:"Personal electronics",html:"<p>Portable audio, pagers, electronic organizers, calculators, cameras, cellular telephones, watches, and compact computers vary by income and profession. Film photography remains normal while digital imaging expands first among media, technical, institutional, and affluent users.</p>"},
      {id:"robots",title:"Domestic automation and robotics",html:"<p>Japan leads specialized household machines for cleaning, monitoring, mobility assistance, elder care, and repetitive domestic tasks. These are bounded appliances and service systems rather than general humanoid servants.</p><p>Elsewhere, programmed heating, security, kitchen, garden, and workshop devices spread without receiving the same robotic public identity.</p>"},
      {id:"service",title:"Installation and repair",html:"<p>Dealers, certified technicians, local computer shops, telephone engineers, appliance services, software houses, and knowledgeable family members keep systems functioning. Documentation, spare parts, adapters, and compatibility services remain decisive.</p><p>A product without service can become useless long before its physical life ends.</p>"},
      {id:"variation",title:"Variation",html:"<p>Metropolitan and affluent households adopt first. Rural lines, unstable power, import controls, language support, cramped housing, colonial status, and income change the practical value of the same device.</p><p>The typical household is therefore a range of systems rather than one universal inventory.</p>"}
    ],
    related:[{href:"microelectronic-household.html",kicker:"Earlier transition",label:"Microelectronic Household"},{href:"affluent-household-1985.html",kicker:"Earlier baseline",label:"Affluent Household in 1985"},{href:"domestic-communications-in-2000.html",kicker:"Network use",label:"Domestic Communications in 2000"},{href:"consumer-telecommunications.html",kicker:"Communications history",label:"Consumer Telecommunications"},{href:"platform-society.html",kicker:"System context",label:"Platform Society"}],
    facts:[["Reference year","2000"],["Ordinary television","CRT"],["Personal computer","Common in prosperous metropolitan homes"],["Network connection","Widespread but not universal or uniform"],["Physical media","Still important"],["Pocket cellular telephone","Familiar and increasingly common, not universal"],["Domestic robotics","Specialized; strongest in Japan"],["General household robot","Not ordinary"]]
  }),

  "work-and-employment-in-2000": matureEverydayArticle({
    title:"Work and employment in 2000",
    category:"Labour history",
    infoboxKicker:"Millennium workplace",
    landscape:{src:"assets/diagrams/work-employment-2000.svg",alt:"Millennium employment system linking production, office, service, technical, care, and household work",caption:"Automation expands the demand for technical and service work even as it reduces labor in particular production and clerical tasks"},
    lead:"Work and employment in 2000 are shaped by automated production, computerized offices, credentialed technical service, large corporate and public systems, persistent small firms, and extensive care and household labor. The principal change since 1985 is not the disappearance of work but the extension of electronic scheduling, records, diagnostics, identity, and supervision across occupations.",
    canon:"Mass office computing, automated industry, the certified technician class, corporate ecosystems, home enterprise, strong Japanese company institutions, German estates and works schools, Commonwealth technical services, American corporate patronage, Latin corporative provision, and unequal imperial credential access are established. Employment totals, wages, union density, hours, occupational rosters, and unemployment series remain open.",
    sections:[
      {id:"production",title:"Production",html:"<p>Robots, numerically controlled machinery, process computers, sensors, logistics systems, and quality records reduce some repetitive labor while increasing maintenance, programming, calibration, inspection, and supply work.</p><p>Japanese firms remain the leading model of deeply automated production, with German and American industries adopting different combinations under competitive pressure.</p>"},
      {id:"office",title:"Office work",html:"<p>Word processing, electronic worksheets, databases, scheduling, messaging, document imaging, and networked records are standard in large organizations. Paper survives for signatures, archives, field use, legal proof, and institutions whose systems cannot communicate directly.</p>"},
      {id:"technical",title:"Technical employment",html:"<p>Technicians install, diagnose, certify, and repair computers, telecommunications, vehicles, medical equipment, power, controls, refrigeration, and aerospace systems. Credentials and access to current documentation create both mobility and hierarchy.</p>"},
      {id:"service",title:"Service and care work",html:"<p>Retail, hospitality, transport, cleaning, food, education, health, elder care, childcare, repair, administration, and security employ large populations. Electronic systems organize these jobs without making their physical and interpersonal labor disappear.</p>"},
      {id:"small",title:"Small firms and household enterprise",html:"<p>Personal computers, parcel networks, telephone service, local credit, and specialized software support accounting, publishing, tutoring, design, repair, food, crafts, insurance, games, and mail or network order from small premises and homes.</p><p>The American cottage-industry revival is the strongest case, but similar firms exist within every bloc's regulatory system.</p>"},
      {id:"institutions",title:"Employment institutions",html:"<p>German occupational estates, Japanese company systems, Commonwealth public and commercial employers, American corporate portfolios, and Latin corporative bodies mediate training, benefits, discipline, and advancement differently. None produces a frictionless labor market.</p>"},
      {id:"gender",title:"Gender and family",html:"<p>Women are common in professional, clerical, educational, medical, technical, retail, and administrative work. Marriage and parenthood still alter hours, promotion, residence, and access to benefits more sharply for women.</p><p>Part-time work, family firms, and multigenerational care connect paid and unpaid labor.</p>"},
      {id:"inequality",title:"Citizens, associates, and subjects",html:"<p>Imperial subjects and associated-state workers can operate advanced systems while facing ceilings in ownership, management, credentials, movement, or strategic clearance. Technical training may create a local middle class without equal control over the system it maintains.</p>"}
    ],
    related:[{href:"office-automation.html",kicker:"Workplace transition",label:"Office Automation"},{href:"technician-class.html",kicker:"Technical stratum",label:"Certified Technician Class"},{href:"american-cottage-industry-revival.html",kicker:"Household enterprise",label:"American Cottage-Industry Revival"},{href:"corporate-geopolitics-americas.html",kicker:"Corporate systems",label:"Corporate Geopolitics in the Americas"},{href:"everyday-life-in-imperial-peripheries-2000.html",kicker:"Unequal employment",label:"Everyday Life in Imperial Peripheries"}],
    facts:[["Reference year","2000"],["Principal workplace change","Electronic records, scheduling, diagnostics, and supervision"],["Automation effect","Task displacement with technical and service expansion"],["Paper records","Persistent"],["Small enterprise","Supported by computers, credit, telecommunications, and parcels"],["Care work","Large and labor-intensive"],["Credentials","Central to mobility"],["Principal inequality","Access to management, ownership, and strategic clearance"]]
  }),

  "domestic-communications-in-2000": matureEverydayArticle({
    title:"Domestic communications in 2000",
    category:"Communications history",
    infoboxKicker:"Household and personal communications",
    landscape:{src:"assets/diagrams/domestic-communications-2000.svg",alt:"Communications layers from physical post and fixed telephone through broadcast, mobile service, national networks, and Weltnetz gateways",caption:"Households use several overlapping media; Weltnetz connects systems without replacing national services or physical delivery"},
    lead:"Domestic communications in 2000 combine fixed telephones, answering systems, fax, radio, television, satellite distribution, pagers, cellular service, electronic mail, forums, information services, networked games, post, and parcel delivery. Weltnetz supplies the common international network layer, while national and corporate services continue to control most accounts, content, billing, and identity.",
    canon:"Weltnetz's mature international role, Bridge compatibility, Concord's closed prestige, several bloc network ecologies, electronic mail and information services, mass household computing, fixed-line continuity, cellular growth, fax, broadcast, satellite links, and physical parcel complements are established. Subscriber totals, bandwidth, access prices, mobile coverage, service brands, and household adoption rates remain open.",
    sections:[
      {id:"telephone",title:"Telephone",html:"<p>The fixed telephone remains the most dependable household interactive service. Multiple extensions, answering machines, recording systems, business lines, and modem use are common in prosperous homes.</p><p>Public booths and workplace telephones remain important where household service is unavailable or monitored.</p>"},
      {id:"mobile",title:"Mobile service",html:"<p>Cellular telephones have moved beyond car installation and elite executive use, particularly in cities, business, transport, and technical professions. Pagers remain cheaper, smaller, and useful for workers who need to be summoned rather than continuously connected.</p><p>Coverage, roaming, battery life, price, and bloc standards prevent universality.</p>"},
      {id:"networks",title:"Household networks",html:"<p>Users reach electronic mail, forums, banking, reference, software libraries, news, games, education, and specialist communities through national services and Weltnetz gateways. The <a href='bridge-operating-environment.html'>Bridge</a> environment converts documents and applications among incompatible systems.</p>"},
      {id:"identity",title:"Accounts and identity",html:"<p>Government, employer, school, bank, network, and commercial identities remain separate. Some systems join them more closely than others.</p><p>The absence of one universal login limits convenience while reducing the consequences of failure or exclusion from a single service.</p>"},
      {id:"broadcast",title:"Broadcast and recorded media",html:"<p>Radio and television remain the principal common mass media. Cable, satellite distribution, recorded video, and home computers increase choice without ending scheduled national broadcasting.</p><p>News of wars, elections, launches, and lunar events can be watched widely while commentary remains bloc-specific.</p>"},
      {id:"documents",title:"Fax, post, and documents",html:"<p>Fax remains useful for signatures, diagrams, handwriting, seals, and incompatible character systems. Post and parcels deliver originals, goods, software media, catalogs, and personal correspondence.</p><p>Electronic communication often initiates a transaction that still concludes physically.</p>"},
      {id:"privacy",title:"Privacy and monitoring",html:"<p>Telephone records, network gateways, workplace systems, billing, censorship, and security services create extensive metadata and opportunities for interception. German, Japanese, American, Commonwealth, and Latin law set different limits and remedies.</p><p>Users adapt through separate accounts, physical media, face-to-face exchange, and informal technical practices.</p>"},
      {id:"inequality",title:"Unequal access",html:"<p>Urban technical households can possess several channels while rural or colonial communities depend on radio, shared telephone, public terminal, postal route, or employer communications. Language support and political status can matter as much as line availability.</p>"}
    ],
    related:[{href:"weltnetz.html",kicker:"International layer",label:"Weltnetz"},{href:"bridge-operating-environment.html",kicker:"Compatibility",label:"Bridge Operating Environment"},{href:"consumer-telecommunications.html",kicker:"Earlier development",label:"Consumer Telecommunications"},{href:"computing-networks.html",kicker:"Network history",label:"Computing and Global Networks"},{href:"household-technology-in-2000.html",kicker:"Domestic devices",label:"Household Technology in 2000"}],
    facts:[["Reference year","2000"],["Principal household interactive service","Fixed telephone"],["Mobile service","Established and growing, not universal"],["International data layer","Weltnetz"],["Compatibility environment","Bridge"],["Mass media","Radio and television"],["Document bridge","Fax"],["Physical complement","Post and parcel delivery"]]
  }),

  "shopping-and-consumer-services-in-2000": matureEverydayArticle({
    title:"Shopping and consumer services in 2000",
    category:"Consumer history",
    infoboxKicker:"Retail, payment, delivery, and repair",
    landscape:{src:"assets/diagrams/consumer-services-2000.svg",alt:"Consumer transaction chain from discovery and payment through delivery, installation, warranty, and repair",caption:"Network ordering changes discovery and payment before it eliminates stores, warehouses, transport, installation, or repair"},
    lead:"Shopping and consumer services in 2000 remain centered on physical stores, markets, dealerships, catalogs, banks, repair shops, and delivery networks while telephone and network ordering expand. Electronic systems change inventory, comparison, payment, and coordination earlier than they replace the material institutions that move and maintain goods.",
    canon:"Protected cross-bloc commerce, distinct product ecosystems, electronic records, bank cards and automated cash, physical retail and parcels, American corporate platforms, Japanese company distribution, German certification and service, Commonwealth commercial-public networks, Latin design-led goods, and post-crash strategic ownership controls are established. Retail shares, prices, store chains, online volumes, card systems, and consumer law remain open.",
    sections:[
      {id:"places",title:"Places of purchase",html:"<p>Department stores, supermarkets, neighborhood shops, markets, cooperatives, manufacturer dealers, specialized electronics shops, service counters, and informal trading continue to divide the market. National geography and planning shape which dominates.</p>"},
      {id:"discovery",title:"Catalogs and electronic discovery",html:"<p>Printed catalogs, advertising, television, telephone information, network listings, reviews, forums, and electronic inventories help households locate goods. Ordering at a terminal or computer is commonest for standardized goods, tickets, software, business supplies, and repeat purchases.</p>"},
      {id:"payment",title:"Payment",html:"<p>Cash, checks, bank cards, account credit, postal payment, automated cash, employer or cooperative accounts, and electronic transfer coexist. Currency borders and bloc clearing remain visible in international purchases.</p><p>Mexico's gold currency and the wider bullion-clearing system offer alternatives to American fiat settlement.</p>"},
      {id:"delivery",title:"Delivery and collection",html:"<p>Postal systems, parcel firms, rail freight, road carriers, store delivery, local couriers, and customer collection complete most remote purchases. Accurate addresses, customs forms, compatible parts, and return procedures matter as much as the electronic order.</p>"},
      {id:"service",title:"Installation, warranty, and repair",html:"<p>Appliances, computers, vehicles, communications, heating, and professional equipment often require dealer installation or certified service. Warranty can be regional even when the product is international.</p><p>Repairability remains a major consumer value because incompatible parts and controlled imports can make replacement slow.</p>"},
      {id:"foreign",title:"Foreign goods",html:"<p>Japanese electronics, German machinery and appliances, American computers and media, British specialist systems, and Latin designed goods circulate beyond their blocs. Quotas, local assembly, adapters, licensing, censorship, and service arrangements preserve national control.</p>"},
      {id:"crash",title:"After the American depression",html:"<p>The Open Door Depression discredits unrestricted foreign ownership rather than all foreign goods. Strategic assets are closed or divested while consumer trade continues through licenses, branches, protected portfolios, and negotiated access.</p><p>Households experience the settlement through brand changes, service continuity, prices, employment, and political advertising.</p>"},
      {id:"inequality",title:"Access and scarcity",html:"<p>Metropolitan households choose among several channels. Rural, sanctioned, colonial, or poor households may depend on one company store, market day, cooperative, repair trader, mail route, or smuggling network.</p><p>A product shown on television or Weltnetz may remain physically unobtainable.</p>"}
    ],
    related:[{href:"protected-consumer-commerce.html",kicker:"Earlier trade system",label:"Protected Consumer Commerce"},{href:"international-bullion-clearing-system.html",kicker:"Cross-bloc payment",label:"International Bullion-Clearing System"},{href:"american-corporate-space-system.html",kicker:"Corporate network model",label:"American Corporate Space System"},{href:"domestic-communications-in-2000.html",kicker:"Ordering channels",label:"Domestic Communications in 2000"},{href:"everyday-life-in-imperial-peripheries-2000.html",kicker:"Unequal access",label:"Everyday Life in Imperial Peripheries"}],
    facts:[["Reference year","2000"],["Principal retail form","Physical stores and markets"],["Remote ordering","Catalog, telephone, and network"],["Common payments","Cash, check, card, account, and electronic transfer"],["Delivery","Post, parcel, rail, road, and local courier"],["Product value","Serviceability and warranty"],["Cross-bloc goods","Visible but protected"],["Mass storeless commerce","Not established"]]
  }),

  "travel-and-mobility-in-2000": matureEverydayArticle({
    title:"Travel and mobility in 2000",
    category:"Transport history",
    infoboxKicker:"Everyday movement at the millennium",
    landscape:{src:"assets/diagrams/travel-mobility-2000.svg",alt:"Mobility hierarchy from walking and local transit through automobiles, rail, aviation, and professional spaceflight",caption:"Mobility expands by layers; mass terrestrial travel and professional spaceflight remain socially distinct"},
    lead:"Travel and mobility in 2000 combine walking, bicycles, scooters, buses, metros, railways, automobiles, ferries, long-distance coaches, jet aviation, and a small professional space-transport sector. The balance differs sharply by system: America remains automobile-centered, Japan rail-centered, Europe mixed, and imperial peripheries dependent upon the corridors built for military and commercial extraction.",
    canon:"American mass automobile dependence, Japanese compact rail mobility, German motorways and organized touring, British Commonwealth maritime and air routes, Latin scooters and compact cars, container and jet systems, widespread professional orbital transport, and unequal imperial movement controls are established. Passenger totals, timetables, fares, fuel prices, specific routes, visa regimes, and accident rates remain open.",
    sections:[
      {id:"local",title:"Local movement",html:"<p>Walking remains fundamental. Bicycles, scooters, buses, trams, metros, commuter rail, taxis, and private vehicles serve different urban forms. Compact Japanese and European cities support frequent public transport; dispersed American development makes car access more consequential.</p>"},
      {id:"cars",title:"Automobiles",html:"<p>Cars use mature mechanical designs with electronic engine control, diagnostics, safety systems, and navigation on premium or fleet vehicles. Large American vehicles survive beside compacts and utility vehicles; Europe and Japan favor smaller forms.</p><p>Electric cars remain specialized rather than a mass replacement.</p>"},
      {id:"rail",title:"Rail and long-distance surface travel",html:"<p>Railways carry commuters, intercity passengers, mail, and freight across every major system. High-quality corridors coexist with older lines, sleeper services, border inspection, and route changes imposed by the postwar settlement.</p><p>Canada's National Commonwealth Corridor gives transport an explicit sovereignty function.</p>"},
      {id:"air",title:"Civil aviation",html:"<p>Jet airliners, computerized reservations, satellite weather, modern airports, and bloc-spanning carriers make long-distance travel routine for business, officials, prosperous tourists, and migrant families. It is not cheap or politically frictionless everywhere.</p>"},
      {id:"sea",title:"Maritime travel",html:"<p>Ferries, coastal ships, island services, liners, naval transport, and mixed passenger-cargo routes remain important across the Commonwealth, Japanese maritime sphere, Mediterranean, Caribbean, and African coasts. Containerization does not eliminate passenger movement by water.</p>"},
      {id:"borders",title:"Borders and documents",html:"<p>Passports, internal permits, visas, currency rules, customs, security screening, and political status shape international and imperial movement. Associated states can have easier movement within a sphere without receiving equal rights at the center.</p>"},
      {id:"tourism",title:"Tourism",html:"<p>Organized German holidays, Mediterranean resorts, Commonwealth routes, Japanese domestic and imperial travel, American road tourism, pilgrimage, and battlefield memory sustain large travel industries. Television and network information expand knowledge of destinations while travel agents and package institutions remain important.</p>"},
      {id:"space",title:"Space transport",html:"<p>Scheduled crew and cargo operations connect Earth orbit, stations, and the Moon. Passengers are astronauts, technicians, scientists, officials, workers, journalists, and a small number of wealthy or sponsored visitors.</p><p>Spaceflight is a visible part of public life without becoming ordinary household mobility.</p>"}
    ],
    related:[{href:"supersonic-passenger-aircraft.html",kicker:"Air transport",label:"Supersonic Passenger Aircraft"},{href:"german-motor-industry.html",kicker:"Continental mobility",label:"German Motor Industry"},{href:"national-commonwealth-corridor.html",kicker:"Canadian transport sovereignty",label:"National Commonwealth Corridor"},{href:"cislunar-transportation-economy.html",kicker:"Space transport",label:"Cislunar Transportation Economy"},{href:"shopping-and-consumer-services-in-2000.html",kicker:"Movement of goods",label:"Shopping and Consumer Services in 2000"}],
    facts:[["Reference year","2000"],["American pattern","Automobile-centered"],["Japanese pattern","Rail and compact urban mobility"],["European pattern","Mixed rail, transit, compact vehicles, and aviation"],["Long-distance mode","Jet aviation and rail"],["Imperial movement","Corridor-dependent and legally unequal"],["Orbital travel","Professional and prestigious"],["Mass space tourism","Absent"]]
  }),

  "family-and-household-life-in-2000": matureEverydayArticle({
    title:"Family and household life in 2000",
    category:"Family history",
    infoboxKicker:"Domestic institutions at the millennium",
    landscape:{src:"assets/diagrams/family-household-2000.svg",alt:"Household surrounded by kin, school, church, employer, neighborhood, market, and public institutions",caption:"The household remains embedded in durable institutions even as women work more widely and personal communications expand"},
    lead:"Family and household life in 2000 remain strongly institutional. Marriage, kin, churches and religious bodies, schools, employers, neighborhood organizations, professional associations, and public benefits shape domestic decisions. Female professional work and personal computing expand, while childcare, elder care, domestic labor, family business, and intergenerational obligation remain central to household production.",
    canon:"Stronger marriage continuity than historical late-century America, lower divorce and remarriage churn, smoother fertility change, extensive family and religious institutions, pronatalist policy in several systems, expanding female education and professional work, home enterprise, multigenerational care, and large differences by law and status are established. Marriage rates, household sizes, fertility totals after 1985, divorce law by jurisdiction, childcare systems, and representative families remain open.",
    sections:[
      {id:"forms",title:"Household forms",html:"<p>Married couples with children remain the public norm across the five systems, but single adults, widows and widowers, multigenerational homes, childless couples, extended-family arrangements, service households, and shared urban accommodation are common enough to require ordinary institutions.</p>"},
      {id:"marriage",title:"Marriage and divorce",html:"<p>Marriage law and religious practice vary. Divorce exists but is generally less frequent and more institutionally mediated than in the corresponding historical Western societies.</p><p>The same continuity preserves many families and can keep people in harmful or unhappy marriages longer.</p>"},
      {id:"children",title:"Children and education",html:"<p>Schools, youth bodies, churches, employers, states, and families dispute the formation of children. Technical education, computing, languages, civic history, and national or imperial identity enter curricula unevenly.</p><p>Access to advanced schooling remains one of the strongest lines separating metropolitan citizens from subjects.</p>"},
      {id:"women",title:"Women, work, and domestic labor",html:"<p>Women participate widely in professional, clerical, educational, medical, technical, retail, artistic, and administrative work. Full-time homemaking remains a respected or encouraged path in many systems, especially around young children.</p><p>Household appliances reduce particular tasks without eliminating cooking, cleaning, scheduling, care, and emotional labor.</p>"},
      {id:"elders",title:"Elder care",html:"<p>Longer life and multigenerational obligation increase demand for family care, clinics, home assistance, pensions, accessible transport, and specialized devices. Japan develops the most visible domestic care robotics, while other systems rely more heavily on family, parish, municipal, employer, or public services.</p>"},
      {id:"home-work",title:"Home enterprise",html:"<p>Computers, telephones, parcels, local credit, and software support bookkeeping, teaching, publishing, repair, design, food, crafts, sales, and professional services from the home. Household business can expand autonomy while lengthening work into domestic time.</p>"},
      {id:"religion",title:"Religion and association",html:"<p>Parishes, congregations, shrines, temples, neighborhood bodies, clubs, veterans, professional estates, company associations, and civic organizations provide childcare, welfare, ritual, recreation, advice, and political contact.</p><p>Their strength varies, but few households encounter state and market as the only collective institutions.</p>"},
      {id:"inequality",title:"Law and status",html:"<p>Race, nationality, caste, colonial classification, religion, employer, and citizenship can determine permission to marry, residence, benefits, education, movement, or inheritance. The security experienced by recognized households can therefore rest upon the exclusion of others.</p>"}
    ],
    related:[{href:"everyday-life.html",kicker:"Long social history",label:"Everyday Life by Bloc"},{href:"national-health-family-security-act.html",kicker:"American family policy",label:"National Health and Family Security Act"},{href:"household-technology-in-2000.html",kicker:"Domestic equipment",label:"Household Technology in 2000"},{href:"work-and-employment-in-2000.html",kicker:"Paid and unpaid work",label:"Work and Employment in 2000"},{href:"everyday-life-in-imperial-peripheries-2000.html",kicker:"Unequal household rights",label:"Everyday Life in Imperial Peripheries"}],
    facts:[["Reference year","2000"],["Public household norm","Married couple and children"],["Divorce","Legal but generally less frequent"],["Female professional work","Widespread and expanding"],["Domestic labor","Still substantial"],["Elder care","Family plus institutional support"],["Home enterprise","Supported by computers and communications"],["Principal legal divide","Citizenship and imperial status"]]
  }),

  "everyday-life-in-imperial-peripheries-2000": matureEverydayArticle({
    title:"Everyday life in imperial peripheries in 2000",
    category:"Colonial social history",
    infoboxKicker:"Modern systems under unequal status",
    landscape:{src:"assets/diagrams/imperial-peripheries-2000.svg",alt:"Gradient from metropolitan standards through associated-state participation, settler privilege, registered subject communities, and excluded populations",caption:"Infrastructure can spread farther than citizenship, ownership, credentials, or freedom of movement"},
    lead:"Everyday life in imperial peripheries in 2000 combines modern transport, communications, schools, clinics, consumer goods, technical employment, and electronic administration with unequal citizenship, property, movement, education, and political authority. Associated states, protectorates, Reichskommissariats, settler territories, concessions, and subject districts occupy different positions; no single colonial household represents them all.",
    canon:"Sharp metropolitan–colonial inequality, eastern racial categories and settler privilege, MOSAIK registration, Mittelafrika's recognized districts and removable populations, Japanese associated-state development under retained strategic control, Commonwealth layered sovereignty, Latin port-and-corridor administration, and unequal access to advanced credentials are established. Household incomes, access rates, settlement populations, local brands, and representative family biographies remain open.",
    sections:[
      {id:"forms",title:"Administrative forms",html:"<p>A Japanese associated state retains flags, government, schools, police, and citizenship while depending on Japanese corporate systems. An eastern Reichskommissariat applies explicit racial hierarchy. Mittelafrika governs through settlement, district, concession, and registration. Commonwealth and Latin territories combine crowns, compacts, protectorates, ports, and local authorities.</p>"},
      {id:"infrastructure",title:"Infrastructure",html:"<p>Railways, roads, ports, power, radio, telephone, clinics, schools, irrigation, cold chains, and electronic records can improve survival and productivity. Their routes often serve extraction, garrisons, settlers, or strategic corridors before local convenience.</p>"},
      {id:"home",title:"The household",html:"<p>Urban professionals and recognized technical families may own televisions, appliances, telephones, vehicles, and computers similar to metropolitan goods. Rural and excluded communities may share power, radio, water, transport, or terminals and depend on repair markets or remittances.</p><p>Legal status affects whether a household can remain where infrastructure arrives.</p>"},
      {id:"work",title:"Work and credentials",html:"<p>Local engineers, technicians, teachers, nurses, clerks, managers, drivers, and operators maintain advanced systems. Promotion can stop below strategic direction, foreign ownership, military clearance, or the highest credentials.</p><p>Associated-state training broadens the middle class more consistently than racial colonial systems do.</p>"},
      {id:"movement",title:"Movement and residence",html:"<p>Passes, registrations, employer papers, racial status, citizenship, concession boundaries, and police controls shape travel. A railway or road can increase mobility for recognized users while making surveillance and removal more effective.</p>"},
      {id:"consumption",title:"Consumer markets",html:"<p>Company stores, markets, cooperatives, import shops, metropolitan branches, used goods, repair traders, and smuggling divide access. Japanese brands spread widely through the Sphere. German goods follow settler and charter networks, while British and Latin goods follow ports and institutional geography.</p>"},
      {id:"culture",title:"Language, media, and education",html:"<p>Schools and broadcasts carry imperial languages, technical standards, political memory, and consumer culture. Local languages, religions, kinship, music, print, and informal education persist with different levels of protection.</p><p>Korean language endangerment is the most explicit example of modernization joined to sustained assimilation.</p>"},
      {id:"difference",title:"Associated state and colony",html:"<p>An associated state can bargain over taxation, labor, police access, local management, language, and public obligations even when Japanese ownership remains. A racial colony denies that bargaining power to much of its population by design.</p><p>Both may contain modern households. Their residents do not possess the same capacity to change the institutions surrounding them.</p>"}
    ],
    related:[{href:"african-order-in-2000.html",kicker:"Continental comparison",label:"African Order in 2000"},{href:"corporate-politics-geacps.html",kicker:"Associated-state system",label:"Corporate Politics in the GEACPS"},{href:"eastern-reichskommissariats.html",kicker:"Racial empire",label:"Eastern Reichskommissariats"},{href:"mosaic-order.html",kicker:"Mittelafrika social order",label:"Mosaic Order"},{href:"shopping-and-consumer-services-in-2000.html",kicker:"Material access",label:"Shopping and Consumer Services in 2000"}],
    facts:[["Reference year","2000"],["Common condition","Modern infrastructure under unequal political status"],["Associated-state model","Local government under Japanese strategic and corporate primacy"],["Eastern model","Racial category and settler privilege"],["Mittelafrika model","Registered districts, concessions, and removable populations"],["Technical middle class","Present but often ceilinged"],["Consumer access","Urban and status-dependent"],["Uniform colonial household","None"]]
  })
});

function extendEverydayArticle(slug, config) {
  const article = window.deepArticles[slug];
  if (!article) return;
  if (config.title) article.title = config.title;
  if (config.eyebrow) article.eyebrow = config.eyebrow;
  if (config.lead) article.lead = config.lead;
  if (config.canon) article.canon = config.canon;
  if (!article.sections.some(section => section.id === "after-1985")) article.sections.push({id:"after-1985",title:"1985–2000",html:config.html});
  article.related = article.related || [];
  [{href:"everyday-life-in-2000.html",kicker:"Millennium comparison",label:"Everyday Life in 2000"},{href:"household-technology-in-2000.html",kicker:"Material baseline",label:"Household Technology in 2000"}].forEach(item => {
    if (!article.related.some(existing => existing.href === item.href)) article.related.push(item);
  });
  const period = article.facts?.find(row => row[0] === "Period");
  if (period) period[1] = "1950–2000";
  if (config.fact && article.facts && !article.facts.some(row => row[0] === "2000 condition")) article.facts.push(["2000 condition",config.fact]);
  article.sources = [...(article.sources || []),...matureEverydaySources.filter(source => !(article.sources || []).some(existing => existing.href === source.href))];
}

extendEverydayArticle("everyday-life-in-greater-germany",{
  title:"Everyday life in Greater Germany, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Certified, networked metropolitan prosperity",
  html:"<p>After 1985, Weltnetz, mature home computing, electronic records, satellite media, cellular service, and the prestige of permanent space settlement extend the certified consumer order. Most households remain centered on CRT displays, fixed telephones, physical media, automobiles or public transport, and serviceable appliances rather than continuous wireless access.</p><p>Prosperity in the German core remains visibly separated from eastern and African subject conditions. The same networks that simplify travel, accounts, schooling, and employment also deepen administrative knowledge of households.</p>"
});
extendEverydayArticle("everyday-life-in-united-states",{
  title:"Everyday life in the United States, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Recovered platform consumer economy",
  html:"<p>The World Market Boom broadens foreign goods, computing, and corporate services before the Open Door Depression destroys employment, savings, and confidence in unrestricted ownership. Recovery produces a five-party republic and larger domestic corporate portfolios rather than a retreat from consumer technology.</p><p>By 2000 compatible home computers, games, electronic mail, network services, home enterprise, automobiles, cellular telephones, video, and parcel delivery form a mature American household ecology. Access and security vary sharply by region, race, employment, and the losses sustained during the crash.</p>"
});
extendEverydayArticle("everyday-life-in-britain",{
  title:"Everyday life in Britain, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Commonwealth technical and service prosperity",
  html:"<p>Commonwealth space expansion, the 1998 Mars landing, improved planetary communications, and continued high-value technical employment strengthen confidence after 1985. Households use networked public and commercial services while retaining paper, fixed telephones, broadcast institutions, repair culture, and a strong expectation of reliable provision.</p><p>The Cape route, southern African minerals, Commonwealth procurement, and the late political culture of distancing London from devolved abuses remain present beneath metropolitan prosperity.</p>"
});
extendEverydayArticle("everyday-life-in-canada",{
  title:"Everyday life in Canada, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Affluent Commonwealth network society",
  html:"<p>The National Commonwealth Corridor, Arctic communications, avionics, medicine, and distributed space procurement reinforce a household modernity materially close to the United States but institutionally Commonwealth. Computers, network services, satellite links, automobiles, winterized utilities, and long-distance travel are widespread in prosperous regions.</p><p>Provincial, linguistic, northern, Indigenous, and urban–rural differences prevent one national household pattern. Sovereignty continues to be experienced through transport, broadcasting, defense, and the ability to choose non-American routes.</p>"
});
extendEverydayArticle("everyday-life-in-italy",{
  title:"Everyday life in Italy, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Designed, networked corporative consumer order",
  html:"<p>The Latin scudo, multinational space program, Olivetti-derived professional systems, satellite communication, designed electronics, and continuing Catholic and corporative institutions extend the earlier consumer order. Compact cars, scooters, rail, television, video, fixed telephones, computers, and local commercial networks remain characteristic.</p><p>Regional inequality, patronage, restricted labor independence, and the costs of imperial commitments remain visible despite greater material abundance.</p>"
});
extendEverydayArticle("everyday-life-in-occitania",{
  title:"Everyday life in Occitania, 1950–2000",eyebrow:"Everyday life · 1950–2000",
  fact:"Aerospace-linked Mediterranean technical society",
  html:"<p>Aerospace, controls, software, Latin space work, multilingual network services, and Mediterranean commerce deepen the technical middle class after 1985. Urban homes increasingly possess computers, video, network access, cellular service, compact vehicles, and mature appliances while public life remains organized through city, parish, region, profession, and family.</p><p>Younger residents experience Occitania as an ordinary national home rather than a temporary partition, although French language and cross-border culture remain substantial.</p>"
});

